SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(3*10^9);AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");out:=[];for u in [4,10] do J:=JH(81,[u]);cs:=[];for p in [2,5,7,11] do f:=FrobeniusPolynomial(J,p);if Type(f) eq SeqEnum then f:=&*f;end if;Append(~cs,Integers()!Evaluate(f,1));end for;Append(~out,[u,Dimension(J)] cat cs);print "C81_TARGET_GOOD_PRIME_ORDERS",out[#out],"gcd",GCD(cs);end for;Write("work/deg10/continuation_20261030b/C81/target_gcd_orders.m",Sprint(out):Overwrite:=true);print "C81_TARGET_GOOD_PRIME_COMPLETE";quit;
